1	import React from 'react';
2	import { chakra, Drawer, DrawerOverlay, DrawerContent, useMultiStyleConfig } from '@chakra-ui/react';
3	import { ZimmButton } from 'app/components/ui-kits/atoms/zimmButton';
4	
5	const ZIMM_DRAWER_RECIPE = 'ZimmDrawer';
6	
7	export type ZimmDrawerSize = 'large' | 'small' | 'mobile';
8	
9	type ZimmDrawerBaseProps = {
10	  /** Whether the drawer is open. */
11	  isOpen: boolean;
12	  /** Called on backdrop click, Escape, and the close button (all via Chakra's Drawer). */
13	  onClose: () => void;
14	  /** Desktop width variant. Collapses to the mobile treatment below the tablet breakpoint
15	   *  regardless of which value is chosen — see zimmDrawer.css.ts. */
16	  size: ZimmDrawerSize;
17	  children: React.ReactNode;
18	};
19	
20	type ZimmDrawerProps = ZimmDrawerBaseProps &
21	  ({ labelledBy: string; 'aria-label'?: never } | { labelledBy?: never; 'aria-label': string });
22	
23	/**
24	 * Generic right-anchored slide-in drawer shell — overlay, panel, and a Large/Small/Mobile width
25	 * variant, built on Chakra's Drawer primitive (focus trap, initial focus, focus restore,
26	 * body-scroll lock, and Escape/overlay-click-to-close all come from Chakra, not hand-rolled).
27	 * Owns the close button only — no header/tab content of its own, so both a tabbed header
28	 * (ZimmPdpDrawer) and a plain-title header (e.g. a future country/currency selector) can compose
29	 * on top of it.
30	 *
31	 * @param props see ZimmDrawerProps
